#include "gameos/update/UpdateManager.hpp"
#include <filesystem>
namespace gameos::update{bool UpdateManager::validate(const UpdateManifest&m,std::string*e)const{if(m.id.empty()||m.version.empty()){if(e)*e="manifest id/version required";return false;}for(auto&f:m.files)if(f.path.empty()){if(e)*e="patch path required";return false;}return true;}bool UpdateManager::stage(const UpdateManifest&m,const std::string&r,std::string*e){if(!validate(m,e))return false;std::error_code x;std::filesystem::create_directories(r,x);if(x){if(e)*e=x.message();return false;}return true;}bool UpdateManager::apply(const std::string&s,const std::string&i,std::string*e){std::error_code x;for(auto it=std::filesystem::recursive_directory_iterator(s,x);it!=std::filesystem::recursive_directory_iterator();it.increment(x)){if(x)break;auto rel=std::filesystem::relative(it->path(),s,x);auto d=std::filesystem::path(i)/rel;if(it->is_directory())std::filesystem::create_directories(d,x);else{std::filesystem::create_directories(d.parent_path(),x);std::filesystem::copy_file(it->path(),d,std::filesystem::copy_options::overwrite_existing,x);}if(x)break;}if(x){if(e)*e=x.message();return false;}return true;}bool UpdateManager::rollback(const std::string&i,const std::string&b,std::string*e){std::error_code x;std::filesystem::remove_all(i,x);std::filesystem::copy(b,i,std::filesystem::copy_options::recursive|std::filesystem::copy_options::overwrite_existing,x);if(x){if(e)*e=x.message();return false;}return true;}}
